using Microsoft.EntityFrameworkCore; using OrcaFacil.Domain.Entities;
namespace OrcaFacil.Persistence;
public class OrcaFacilDbContext(DbContextOptions<OrcaFacilDbContext> options):DbContext(options){ public DbSet<UserAccount> Users=>Set<UserAccount>(); public DbSet<IssuerProfile> IssuerProfiles=>Set<IssuerProfile>(); public DbSet<Document> Documents=>Set<Document>(); public DbSet<DocumentItem> DocumentItems=>Set<DocumentItem>(); public DbSet<PublicQuote> PublicQuotes=>Set<PublicQuote>(); public DbSet<AuditLog> AuditLogs=>Set<AuditLog>(); public DbSet<SystemLog> SystemLogs=>Set<SystemLog>(); public DbSet<SystemError> SystemErrors=>Set<SystemError>(); public DbSet<UserUsage> UserUsage=>Set<UserUsage>(); public DbSet<Subscription> Subscriptions=>Set<Subscription>(); public DbSet<Payment> Payments=>Set<Payment>(); public DbSet<AdminSetting> AdminSettings=>Set<AdminSetting>(); public DbSet<Notification> Notifications=>Set<Notification>(); protected override void OnModelCreating(ModelBuilder b){ b.HasDefaultSchema("core"); b.Entity<UserAccount>().ToTable("users","identity").HasIndex(x=>x.Email).IsUnique(); b.Entity<IssuerProfile>().ToTable("issuer_profiles","core").HasIndex(x=>x.UserId).IsUnique(); b.Entity<Document>().ToTable("documents","core").HasIndex(x=>new{x.UserId,x.Type,x.Number}).IsUnique(); b.Entity<Document>().HasIndex(x=>x.CreatedAt); b.Entity<Document>().HasIndex(x=>x.Status); b.Entity<DocumentItem>().ToTable("document_items","core").HasIndex(x=>x.DocumentId); b.Entity<PublicQuote>().ToTable("public_quotes","public_access").HasIndex(x=>x.Token).IsUnique(); b.Entity<AuditLog>().ToTable("audit_logs","logs").HasIndex(x=>x.CreatedAt); b.Entity<SystemLog>().ToTable("system_logs","logs"); b.Entity<SystemError>().ToTable("system_errors","logs"); b.Entity<UserUsage>().ToTable("user_usage","core").HasIndex(x=>new{x.UserId,x.Period}).IsUnique(); b.Entity<Subscription>().ToTable("subscriptions","billing"); b.Entity<Payment>().ToTable("payments","billing"); b.Entity<AdminSetting>().ToTable("admin_settings","admin").HasIndex(x=>x.Key).IsUnique(); b.Entity<Notification>().ToTable("notifications","admin").HasIndex(x=>x.UserId); } }
